SELECT 'TC-06-01' AS TEST_ID, 'Healthy: 0% failure' AS TEST_NAME, 0 AS EXPECTED, MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(0.56,0.0007,0.01,0,14,0):failure_prob_day_14::FLOAT AS ACTUAL, CASE WHEN MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(0.56,0.0007,0.01,0,14,0):failure_prob_day_14::FLOAT=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS;
SELECT 'TC-06-02' AS TEST_ID, 'Healthy: RUL>100d' AS TEST_NAME, 100 AS EXPECTED, MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(0.56,0.0007,0.01,0,14,0):rul_days_p50::FLOAT AS ACTUAL, CASE WHEN MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(0.56,0.0007,0.01,0,14,0):rul_days_p50::FLOAT>100 THEN 'PASS' ELSE 'FAIL' END AS STATUS;
SELECT 'TC-06-08' AS TEST_ID, '100 simulations' AS TEST_NAME, 100 AS EXPECTED, MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(3.6,0.03,0.35,20,7,0):num_simulations::INT AS ACTUAL, CASE WHEN MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(3.6,0.03,0.35,20,7,0):num_simulations::INT=100 THEN 'PASS' ELSE 'FAIL' END AS STATUS;
SELECT 'TC-06-09' AS TEST_ID, 'Healthy MONITOR' AS TEST_NAME, 'MONITOR' AS EXPECTED, CASE WHEN MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(0.56,0.0007,0.01,0,14,0):recommended_intervention::VARCHAR LIKE '%MONITOR%' THEN 'MONITOR' ELSE 'OTHER' END AS ACTUAL, CASE WHEN MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(0.56,0.0007,0.01,0,14,0):recommended_intervention::VARCHAR LIKE '%MONITOR%' THEN 'PASS' ELSE 'FAIL' END AS STATUS;
